-- Seed the current city-council rosters for the top-100 US cities (1,048 members)
-- into static_officials so civic lookups in those cities have officials to
-- attribute and ward-filter. Idempotent (ON CONFLICT by id); ids are
-- deterministic and match the import-local-officials scheme, so the importer
-- can re-run over the same roster without creating duplicates.
--
-- District values use the identifier the city's boundary layer reports:
-- numbers ("Ward 1"/"District 9"), letters ("District D" — e.g. Houston A-K),
-- or directional/named wards ("Northeast Ward", "Delaware District").
-- "At-Large" seats are always shown city-wide.

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, party=EXCLUDED.party, office=EXCLUDED.office, level=EXCLUDED.level, state=EXCLUDED.state, district=EXCLUDED.district, city=EXCLUDED.city, coverage_tier=EXCLUDED.coverage_tier, confidence=EXCLUDED.confidence, is_active=true, updated_at=now();

